+  <input type="search" name="q" value="{{ q }}" placeholder="Search by title" />
+  <select name="platform">
+    <option value="">All platforms</option>
+    {% for slug, name in platforms %}
+    <option value="{{ slug }}" {% if platform == slug %}selected{% endif %}>{{ name }}</option>
+    {% endfor %}
+  </select>
+  <select name="sort">
+    <option value="rating" {% if sort == 'rating' %}selected{% endif %}>Sort: Metascore</option>
+    <option value="title" {% if sort == 'title' %}selected{% endif %}>Sort: Title</option>
+    <option value="release" {% if sort == 'release' %}selected{% endif %}>Sort: Release date</option>
